package dwn

import (
	"encoding/json"
	"errors"
	"os"
	"reflect"
	"testing"
)

// Fixtures generated by executing the enbox agent implementation
// (packages/agent/src/types/sync.ts + sync-link-key.ts); see the provenance
// note in messages_test.go.
type linkIdentityFixtureFile struct {
	ProjectionIDs []struct {
		Name      string `json:"name"`
		TenantDID string `json:"tenantDid"`
		Scope     struct {
			Kind      string   `json:"kind"`
			Protocols []string `json:"protocols"`
		} `json:"scope"`
		ProjectionID string `json:"projectionId"`
	} `json:"projectionIds"`
	AuthorizationEpochs []struct {
		Name  string `json:"name"`
		Input struct {
			Kind        string `json:"kind"`
			DelegateDID string `json:"delegateDid"`
			Grants      []struct {
				ID          string `json:"id"`
				DateExpires string `json:"dateExpires"`
				DateGranted string `json:"dateGranted"`
			} `json:"grants"`
		} `json:"input"`
		Epoch string `json:"epoch"`
	} `json:"authorizationEpochs"`
	LinkKeys []struct {
		Name               string `json:"name"`
		TenantDID          string `json:"tenantDid"`
		RemoteEndpoint     string `json:"remoteEndpoint"`
		ProjectionID       string `json:"projectionId"`
		AuthorizationEpoch string `json:"authorizationEpoch"`
		LinkKey            string `json:"linkKey"`
	} `json:"linkKeys"`
	NormalizeSyncProtocols []struct {
		Name       string   `json:"name"`
		Input      []string `json:"input"`
		Normalized []string `json:"normalized"`
	} `json:"normalizeSyncProtocols"`
}

func loadLinkIdentityFixtures(t *testing.T) *linkIdentityFixtureFile {
	t.Helper()
	data, err := os.ReadFile("testdata/link_identity_fixtures.json")
	if err != nil {
		t.Fatalf("reading fixtures: %v", err)
	}
	var file linkIdentityFixtureFile
	if err := json.Unmarshal(data, &file); err != nil {
		t.Fatalf("parsing fixtures: %v", err)
	}
	return &file
}

func TestComputeProjectionIDMatchesTypeScriptFixtures(t *testing.T) {
	file := loadLinkIdentityFixtures(t)
	if len(file.ProjectionIDs) == 0 {
		t.Fatal("no projection ID vectors")
	}
	for _, vector := range file.ProjectionIDs {
		t.Run(vector.Name, func(t *testing.T) {
			scope := SyncScope{Kind: vector.Scope.Kind, Protocols: vector.Scope.Protocols}
			got, err := ComputeProjectionID(vector.TenantDID, scope)
			if err != nil {
				t.Fatalf("ComputeProjectionID: %v", err)
			}
			if got != vector.ProjectionID {
				t.Errorf("projection ID = %s, want %s", got, vector.ProjectionID)
			}
		})
	}
}

func TestComputeAuthorizationEpochMatchesTypeScriptFixtures(t *testing.T) {
	file := loadLinkIdentityFixtures(t)
	if len(file.AuthorizationEpochs) == 0 {
		t.Fatal("no authorization epoch vectors")
	}
	for _, vector := range file.AuthorizationEpochs {
		t.Run(vector.Name, func(t *testing.T) {
			var (
				got string
				err error
			)
			switch vector.Input.Kind {
			case "owner":
				got = ComputeOwnerAuthorizationEpoch()
			case "delegate":
				grants := make([]SyncAuthorizationGrant, len(vector.Input.Grants))
				for i, grant := range vector.Input.Grants {
					grants[i] = SyncAuthorizationGrant{
						ID:          grant.ID,
						DateGranted: grant.DateGranted,
						DateExpires: grant.DateExpires,
					}
				}
				got, err = ComputeDelegateAuthorizationEpoch(vector.Input.DelegateDID, grants)
				if err != nil {
					t.Fatalf("ComputeDelegateAuthorizationEpoch: %v", err)
				}
			default:
				t.Fatalf("unknown epoch kind %q", vector.Input.Kind)
			}
			if got != vector.Epoch {
				t.Errorf("epoch = %s, want %s", got, vector.Epoch)
			}
		})
	}
}

func TestBuildLinkKeyMatchesTypeScriptFixtures(t *testing.T) {
	file := loadLinkIdentityFixtures(t)
	for _, vector := range file.LinkKeys {
		got := BuildLinkKey(vector.TenantDID, vector.RemoteEndpoint, vector.ProjectionID, vector.AuthorizationEpoch)
		if got != vector.LinkKey {
			t.Errorf("%s: link key = %s, want %s", vector.Name, got, vector.LinkKey)
		}
	}
}

func TestNormalizeSyncProtocolsMatchesTypeScriptFixtures(t *testing.T) {
	file := loadLinkIdentityFixtures(t)
	for _, vector := range file.NormalizeSyncProtocols {
		got, err := NormalizeSyncProtocols(vector.Input)
		if err != nil {
			t.Fatalf("%s: NormalizeSyncProtocols: %v", vector.Name, err)
		}
		if !reflect.DeepEqual(got, vector.Normalized) {
			t.Errorf("%s: normalized = %q, want %q", vector.Name, got, vector.Normalized)
		}
	}
}

func TestSyncScopeValidation(t *testing.T) {
	if _, err := NormalizeSyncProtocols(nil); !errors.Is(err, ErrSyncScopeEmptyProtocols) {
		t.Errorf("empty protocols error = %v, want ErrSyncScopeEmptyProtocols", err)
	}
	if _, err := ProtocolSetSyncScope(nil); !errors.Is(err, ErrSyncScopeEmptyProtocols) {
		t.Errorf("empty scope error = %v, want ErrSyncScopeEmptyProtocols", err)
	}
	if _, err := ComputeProjectionID("did:dht:x", SyncScope{Kind: "bogus"}); err == nil {
		t.Error("unknown scope kind must be rejected")
	}
	if _, err := ComputeDelegateAuthorizationEpoch("did:jwk:x", nil); err == nil {
		t.Error("delegate epoch without grants must be rejected")
	}

	// The projection ID must not depend on input protocol order/duplicates.
	a, err := ComputeProjectionID("did:dht:x", SyncScope{Kind: SyncScopeKindProtocolSet, Protocols: []string{"b", "a", "b"}})
	if err != nil {
		t.Fatalf("ComputeProjectionID: %v", err)
	}
	b, err := ComputeProjectionID("did:dht:x", SyncScope{Kind: SyncScopeKindProtocolSet, Protocols: []string{"a", "b"}})
	if err != nil {
		t.Fatalf("ComputeProjectionID: %v", err)
	}
	if a != b {
		t.Error("projection ID must be order/duplicate independent")
	}

	if got := SyncAuthorizationGrantsFromPermissionGrants([]*PermissionGrant{
		{ID: "g1", DateGranted: "2026-01-01T00:00:00.000000Z", DateExpires: "2026-02-01T00:00:00.000000Z"},
	}); len(got) != 1 || got[0].ID != "g1" || got[0].DateExpires != "2026-02-01T00:00:00.000000Z" {
		t.Errorf("SyncAuthorizationGrantsFromPermissionGrants = %+v", got)
	}
}
